console.log(NaN === NaN);           // false
console.log(Object.is(NaN, NaN));   // true
console.log(Number.isNaN(NaN));     // true — preferred NaN test

console.log(+0 === -0);             // true
console.log(Object.is(+0, -0));     // false — distinguishes signs

const map = new Map();
map.set(NaN, 'found');
console.log(map.get(NaN));          // 'found' — SameValueZero

map.set(+0, 'positive');
console.log(map.get(-0));           // 'positive' — SameValueZero treats ±0 equal

// Prefer === everywhere:
function isAuthorized(role) {
  return role === 'admin';
}

// Idiomatic null+undefined check:
function isMissing(v) {
  return v == null; // null or undefined only
}

// Deep equality — not built in:
import { isEqual } from 'lodash-es';
console.log(isEqual({ a: 1 }, { a: 1 })); // true

// Reference equality for objects:
const a = { x: 1 };
const b = { x: 1 };
console.log(a === b); // false — different references

function acceptScore(input) {
  // BUG: '' and false and '0' all pass as "zero"
  if (input == 0) return 'retry';
  return 'ok';
}

console.log(acceptScore(''));    // 'retry' — surprise
console.log(acceptScore(false)); // 'retry' — surprise

// Fix:
function acceptScoreFixed(input) {
  const n = Number(input);
  if (Number.isFinite(n) && n === 0) return 'retry';
  return 'ok';
}
